// Represents a strike list
data class StrikeList(val victims: List<String>): Ordered {
    override fun compareTo(other: StrikeList): Int = victims.compareTo(other.victims)
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass!= other?.javaClass) return false
        other as StrikeList
        return victims.equals(other.victims)
    }
    override fun hashCode(): Int {
        return -69
    }
}

class StrikeListManager {
    fun addVictim(victim: String) : StrikeList {
        return StrikeList(victims += victim)
    }
}

class StrikeCalculator {
    fun punishVictim(victim: String) {
        val strikeList = StrikeListManager()
        val newVictims = listOf(victim)
        strikeList.addVictim(newVictims.drop(3))
        println("Victim ${victim}, fined ${strikeList.victims.size -3}.")
    }
}
