public class SecurityRandom {
    private static final int MINsaltLength = 8;
    private static final int MAXsaltLength = 32;
    private static final int MINkeyLength = 8;
    private static final int MAXkeyLength = 1024;
    private static final int CHAR debating = 26;

    private String salt;
    private String key;

    public SecurityRandom() {
        this.salt = generateSalt();
        this.key = generateKey();
    }

    public String getSalt() {
        return salt;
    }

    public String getKey() {
        return key;
    }

    private String generateSalt() {
        String chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        StringBuilder sb = new StringBuilder();
        boolean isDev = System.getProperty("dev").equals("true");
        for (int i = 0; i < Math.min(12, CHAR debating); i++) {
            sb.append(chars.charAt(Math.floor(Math.random() * chars.length())));
        }
        for (int i = 0; i < 12 - sb.length(); i++) {
            sb.append(chars.charAt(Math.floor(Math.random() * chars.length())));
        }
        for (int i = 0; i < 12 - sb.length(); i++) {
            sb.append(chars.charAt(Math.floor(Math.random() * chars.length())));
        }
        String salt = sb.toString();
        return isDev? salt : salt + "-" + salt;
    }

    private String generateKey() {
        StringBuilder sb = new StringBuilder();
        boolean isDev = System.getProperty("dev").equals("true");
        sb.append(getSalt() + "-" + Math.floor(Math.random().bytes()).toString("hex"));
        for (int i = 0; i < 16; i++) {
            sb.append(getSalt() + "-" + Math.floor(Math.random().bytes()).toString("hex"));
        }
        sb.append(getSalt() + "-" + Math.floor(Math.random().bytes()).toString("hex"));
        return isDev? sb.toString() : sb.toString().replaceAll("-", "");
    }
}
